export const ADMINISTRATION_STORAGE_KEY="infobridgeindia.administration.v2";

// Historical application modules that an old bootstrap incorrectly created as departments.
// Names are not used for retirement: only deterministic system row IDs are safe evidence.
const LEGACY_MODULE_DEPARTMENTS=Object.freeze([
  {code:"FIN",name:"Finance & Accounting"},{code:"SALES",name:"Sales & CRM"},
  {code:"PUR",name:"Purchases & Procurement"},{code:"INV",name:"Inventory & Warehouse"},
  {code:"HR",name:"HR & Payroll"},{code:"PROJ",name:"Projects & Operations"},
  {code:"DOC",name:"Documents"},{code:"APR",name:"Internal Requests"},
  {code:"BANK",name:"Banking"},{code:"RPT",name:"Reports & Analytics"},
  {code:"ADMIN",name:"Administration"}
]);

// Compatibility exports. InfoBridgeIndia intentionally has no default departments and
// no implicit mapping from organizational departments to application module access.
export const DEFAULT_DEPARTMENTS=Object.freeze([]);
export const DEPARTMENT_MODULE_BY_CODE=Object.freeze({});
const norm=value=>String(value||"").trim().toLowerCase();
const safe=value=>String(value||"COMPANY").replace(/[^a-z0-9_-]+/gi,"-").replace(/^-|-$/g,"").toUpperCase();
export const stableDepartmentId=(companyId,code)=>`DEP-${safe(companyId)}-${safe(code)}`;
function assignChanged(row,values){let changed=false;for(const[key,value]of Object.entries(values))if(row[key]!==value){row[key]=value;changed=true}if(changed)row.updatedAt=new Date().toISOString();return row}

/** Non-destructively retire only rows provably generated by the former bootstrap. */
export function ensureDefaultDepartments(state,companyIds){
  state.departments=Array.isArray(state.departments)?state.departments:[];
  state.departmentDefaultAccess=Array.isArray(state.departmentDefaultAccess)?state.departmentDefaultAccess:[];
  const ids=companyIds||state.companies?.map(company=>company.id)||[state.currentCompanyId];
  for(const companyId of ids.filter(Boolean))for(const item of LEGACY_MODULE_DEPARTMENTS){
    const generatedId=stableDepartmentId(companyId,item.code);
    const row=state.departments.find(candidate=>candidate.companyId===companyId&&candidate.id===generatedId&&(candidate.isSystem===true||candidate.systemDefault===true));
    if(row)assignChanged(row,{active:false,retiredSystemDefault:true,retiredReason:"legacy-module-department",retiredAt:row.retiredAt||new Date().toISOString()});
  }
  return state;
}

export function orderedDepartments(state,companyId=state?.currentCompanyId,{activeOnly=true,includeIds=[]}={}){
  const included=new Set(includeIds.filter(Boolean));
  return(state?.departments||[]).filter(row=>row.companyId===companyId&&(!row.retiredSystemDefault||included.has(row.id))&&(!activeOnly||row.active!==false||included.has(row.id))).sort((a,b)=>String(a.name||"").localeCompare(String(b.name||"")));
}
export function readDepartmentState(storage=globalThis.InfoBridgeWorkspaceStorage||globalThis.localStorage){try{const state=JSON.parse(storage?.getItem(ADMINISTRATION_STORAGE_KEY)||"null");return state&&Array.isArray(state.departments)?state:{departments:[],companies:[],currentCompanyId:""}}catch{return{departments:[],companies:[],currentCompanyId:""}}}
export function currentCompanyId(storage=globalThis.InfoBridgeWorkspaceStorage||globalThis.localStorage,state){return state?.currentCompanyId||storage?.companyId||globalThis.InfoBridgeCompany?.companyId||""}
export function sharedDepartments({includeIds=[],activeOnly=true,storage=globalThis.InfoBridgeWorkspaceStorage||globalThis.localStorage}={}){const state=readDepartmentState(storage),companyId=currentCompanyId(storage,state),authoritativeScope=Boolean(storage?.companyId&&storage.companyId===companyId),scopedState=authoritativeScope?{...state,departments:(state.departments||[]).map(row=>row.companyId?row:{...row,companyId})}:state;return orderedDepartments(scopedState,companyId,{activeOnly,includeIds})}
export function departmentSourceDiagnostics({includeIds=[],storage=globalThis.InfoBridgeWorkspaceStorage||globalThis.localStorage}={}){const state=readDepartmentState(storage),companyId=currentCompanyId(storage,state),raw=state.departments||[],resolved=sharedDepartments({includeIds,storage});return{source:storage?.companyId?"authoritative-workspace":"browser-fallback",storageCompanyId:storage?.companyId||"",profileCompanyId:globalThis.InfoBridgeCompany?.companyId||"",stateCompanyId:state.currentCompanyId||"",resolvedCompanyId:companyId,rawCount:raw.length,rawCustomCount:raw.filter(row=>!(row.isSystem||row.systemDefault)).length,resolvedCount:resolved.length,resolvedDepartments:resolved.map(row=>({id:row.id,name:row.name,active:row.active!==false,companyId:row.companyId||companyId}))}}
export function sharedDepartmentName(id,fallback="",options={}){return sharedDepartments({...options,activeOnly:false,includeIds:[id]}).find(row=>row.id===id)?.name||fallback||"—"}
export function departmentSelectOptions(selected="",options={}){return[{id:"",name:"Select department"},...sharedDepartments({...options,includeIds:selected?[selected]:[]})]}

export function absorbLegacyDepartments(legacy=[],storage=globalThis.InfoBridgeWorkspaceStorage||globalThis.localStorage){
  const state=readDepartmentState(storage),companyId=currentCompanyId(storage,state),map=new Map();if(!companyId)return map;ensureDefaultDepartments(state,[companyId]);
  for(const old of legacy){
    let row=state.departments.find(item=>item.companyId===companyId&&!item.retiredSystemDefault&&((old.id&&item.id===old.id)||norm(item.name)===norm(old.name)||(old.code&&norm(item.code)===norm(old.code))));
    if(!row){let code=String(old.code||old.name||"DEPT").toUpperCase().replace(/[^A-Z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,16)||"DEPT",suffix=2;while(state.departments.some(item=>item.companyId===companyId&&!item.retiredSystemDefault&&item.id!==old.id&&norm(item.code)===norm(code)))code=`${code.slice(0,13)}-${suffix++}`;const timestamp=new Date().toISOString();row={...old,id:old.id||stableDepartmentId(companyId,code),companyId,code,active:old.active!==false,isSystem:false,systemDefault:false,retiredSystemDefault:false,createdAt:old.createdAt||timestamp,updatedAt:timestamp};state.departments.push(row)}
    map.set(old.id,row.id);
  }
  storage?.setItem(ADMINISTRATION_STORAGE_KEY,JSON.stringify(state));return map;
}
export function saveSharedDepartment(value,storage=globalThis.InfoBridgeWorkspaceStorage||globalThis.localStorage){const state=readDepartmentState(storage),companyId=currentCompanyId(storage,state),name=String(value.name||"").trim();if(!companyId||!name)throw Error("Department name is required");const found=state.departments.find(row=>row.companyId===companyId&&!row.retiredSystemDefault&&norm(row.name)===norm(name));if(found)return found;let code=String(value.code||name).toUpperCase().replace(/[^A-Z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,16)||"DEPT";let suffix=2;while(state.departments.some(row=>row.companyId===companyId&&!row.retiredSystemDefault&&norm(row.code)===norm(code)))code=`${code.slice(0,13)}-${suffix++}`;const timestamp=new Date().toISOString(),row={...value,id:value.id||stableDepartmentId(companyId,code),companyId,name,code,active:value.active!==false,isSystem:false,systemDefault:false,retiredSystemDefault:false,createdAt:value.createdAt||timestamp,updatedAt:timestamp};state.departments.push(row);storage?.setItem(ADMINISTRATION_STORAGE_KEY,JSON.stringify(state));return row}
